#!/usr/bin/env python3
"""Keep one copy of the agent rules every repository shares.

agent-rules/shared.md is the only place the shared rules are written. `sync`
copies them between markers into each repository's AGENTS.md, together with a
CI workflow and a copy of this file, so the repository can check itself.
The BEGIN marker carries a hash of the block, so a hand edit is detectable
without network access.

Commands:
  render                 Print the block that sync writes.
  sync REPO_DIR...       Write the block, the workflow and this checker into each checkout.
  check REPO_DIR...      Fail unless each checkout matches agent-rules/shared.md.
  check --sealed DIR     Fail if the block was edited by hand, or AGENTS.md itself has gone stale
                         (run by each repository's CI). See "AGENTS.md checks" below.
  check --remote [REPO]  Check repositories on GitHub through `gh api` (default: agent-rules/consumers.json).
                         Reads each default branch. This is the only check that catches drift from shared.md.

The copy that sync writes into a repository's .github/ only supports `check --sealed`.

AGENTS.md checks (local `check`, outside the shared block):
  - `until <date>` and `TODO(<date>)` with a date that has passed. Delete or update the line.
  - Backticked repository paths (a file with an extension, no wildcards or placeholders)
    that do not exist in the checkout.
  - An optional word budget. A repository sets it in .github/shared-agent-rules/config.json:
      {"maxWords": 1200, "excludeSections": ["Review guidelines"], "ignorePaths": ["docs/not-yet.md"]}
    Words in the shared block and in excluded sections are not counted.

Standard library only.
"""
from __future__ import annotations

import argparse
import base64
import datetime
import hashlib
import json
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SHARED = ROOT / "agent-rules" / "shared.md"
CONSUMERS = ROOT / "agent-rules" / "consumers.json"

SOURCE = "henrypitmandigital/agent-skills agent-rules/shared.md"
BLOCK_RE = re.compile(
    r"<!-- BEGIN:shared-agent-rules sha256=(?P<sha>[0-9a-f]{64}) .*?-->\n(?P<body>.*?)<!-- END:shared-agent-rules -->(?:\n|\Z)",
    re.S,
)
CHECKER_PATH = ".github/shared-agent-rules/agent_rules.py"
WORKFLOW_PATH = ".github/workflows/shared-agent-rules.yml"
SYNC_HINT = "run: python3 tools/agent_rules.py sync <this checkout> from a henrypitmandigital/agent-skills checkout"
CONFIG_PATH = ".github/shared-agent-rules/config.json"
MONTHS = {m: i for i, m in enumerate("Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec".split(), 1)}
UNTIL_RE = re.compile(r"\buntil\s+(?:(\d{1,2})\s+([A-Z][a-z]{2,8})\s+(\d{4})|(\d{4})-(\d{2})-(\d{2}))")
TODO_RE = re.compile(r"TODO\((\d{4})-(\d{2})-(\d{2})\)")
CODE_RE = re.compile(r"`([^`\n]+)`")
FILE_PATH_RE = re.compile(r"[A-Za-z0-9_.-]+(?:/[A-Za-z0-9_.-]+)+\.[A-Za-z0-9]{1,5}")
HEADING_RE = re.compile(r"^(#{1,6})\s+(.*?)\s*$")

WORKFLOW = f"""\
# Generated by {SOURCE.split()[0]} tools/agent_rules.py sync. Do not edit.
name: Shared agent rules

on:
  pull_request:
  push:
    branches: [main]

permissions:
  contents: read

jobs:
  shared-agent-rules:
    runs-on: ubuntu-latest
    timeout-minutes: 5
    steps:
      - uses: actions/checkout@v4
      - run: python3 {CHECKER_PATH} check --sealed .
"""


def digest(body: str) -> str:
    return hashlib.sha256(body.encode("utf-8")).hexdigest()


def render(body: str) -> str:
    return (
        f"<!-- BEGIN:shared-agent-rules sha256={digest(body)} "
        f"generated from {SOURCE}; edit it there, then run tools/agent_rules.py sync -->\n"
        f"{body}<!-- END:shared-agent-rules -->\n"
    )


def canonical_body() -> str:
    if not SHARED.is_file():
        raise SystemExit(
            f"{SHARED} not found. This copy of the checker only supports `check --sealed`; "
            "run render, sync and check from a henrypitmandigital/agent-skills checkout."
        )
    return SHARED.read_text(encoding="utf-8")


def with_block(agents_md: str, body: str) -> str:
    block = render(body)
    matches = list(BLOCK_RE.finditer(agents_md))
    if len(matches) > 1:
        raise SystemExit("AGENTS.md has more than one shared-agent-rules block; delete all but one, then sync again")
    if matches:
        return agents_md[: matches[0].start()] + block + agents_md[matches[0].end():]
    heading = re.search(r"^# .*\n", agents_md, re.M)
    front_matter = re.match(r"---\n.*?\n---\n", agents_md, re.S)
    at = heading.end() if heading else front_matter.end() if front_matter else 0
    return agents_md[:at] + ("\n" if at else "") + block + "\n" + agents_md[at:].lstrip("\n")


def problems_for(
    agents_md: str | None,
    claude_md_exists: bool,
    expected: str | None,
    files: dict[str, str | None] | None = None,
) -> list[str]:
    """expected=None checks only that the block is sealed; files maps generated paths to their contents."""
    if claude_md_exists:
        return ["CLAUDE.md exists. Delete it: Claude Code reads AGENTS.md when no CLAUDE.md is present."]
    if agents_md is None:
        return [f"AGENTS.md is missing; {SYNC_HINT}"]
    matches = list(BLOCK_RE.finditer(agents_md))
    if not matches:
        return [f"AGENTS.md has no shared-agent-rules block; {SYNC_HINT}"]
    if len(matches) > 1:
        return ["AGENTS.md has more than one shared-agent-rules block; delete all but one"]
    sha, body = matches[0]["sha"], matches[0]["body"]
    found = []
    if digest(body) != sha:
        found.append(
            "The shared-agent-rules block in AGENTS.md was edited by hand. Put repository-specific rules "
            "outside the block, or change agent-rules/shared.md in henrypitmandigital/agent-skills and sync every repository."
        )
    elif expected is not None and body != expected:
        found.append(f"The shared-agent-rules block in AGENTS.md is older than agent-rules/shared.md; {SYNC_HINT}")
    if expected is not None and files is not None:
        for path, want in generated_files().items():
            if files.get(path) != want:
                found.append(f"{path} is missing or differs from what sync writes; {SYNC_HINT}")
    return found


def parse_until(match: re.Match) -> datetime.date | None:
    day, month, year, iso_year, iso_month, iso_day = match.groups()
    try:
        if iso_year:
            return datetime.date(int(iso_year), int(iso_month), int(iso_day))
        return datetime.date(int(year), MONTHS[month[:3]], int(day))
    except (KeyError, ValueError):
        return None


def doc_problems(agents_md: str, repo: Path, today: datetime.date, config: dict) -> list[str]:
    """Stale-text checks on AGENTS.md outside the shared block."""
    masked = BLOCK_RE.sub(lambda m: re.sub(r"[^\n]", "", m.group(0)), agents_md)
    found = []
    ignore = set(config.get("ignorePaths", []))
    exclude = set(config.get("excludeSections", []))
    words, skip_level = 0, None
    for number, line in enumerate(masked.split("\n"), 1):
        for match in UNTIL_RE.finditer(line):
            date = parse_until(match)
            if date and date < today:
                found.append(f"AGENTS.md line {number}: '{match.group(0)}' has passed. Update the line or delete it.")
        for match in TODO_RE.finditer(line):
            date = datetime.date(int(match[1]), int(match[2]), int(match[3]))
            if date < today:
                found.append(f"AGENTS.md line {number}: '{match.group(0)}' is overdue. Do it or delete it.")
        for token in CODE_RE.findall(line):
            path = re.sub(r":\d+(?:-\d+)?$", "", token.split("#")[0])
            if (
                FILE_PATH_RE.fullmatch(path)
                and not path.startswith(("@", "http"))
                and path not in ignore
                and not (repo / path).exists()
            ):
                found.append(f"AGENTS.md line {number}: `{path}` does not exist in this repository.")
        heading = HEADING_RE.match(line)
        if heading:
            level = len(heading[1])
            if skip_level is not None and level <= skip_level:
                skip_level = None
            if skip_level is None and heading[2] in exclude:
                skip_level = level
        if skip_level is None:
            words += len(line.split())
    limit = config.get("maxWords")
    if limit and words > limit:
        found.append(
            f"AGENTS.md is {words} words, over the {limit}-word budget in {CONFIG_PATH}. "
            "Move detail into docs or a skill and leave a pointer."
        )
    return found


def read_config(repo: Path) -> dict | str:
    raw = read_local(repo, CONFIG_PATH)
    if raw is None:
        return {}
    try:
        data = json.loads(raw)
    except json.JSONDecodeError as error:
        return f"{CONFIG_PATH} is not valid JSON: {error}"
    return data if isinstance(data, dict) else f"{CONFIG_PATH} must be a JSON object"


def generated_files() -> dict[str, str]:
    return {
        WORKFLOW_PATH: WORKFLOW,
        CHECKER_PATH: Path(__file__).read_text(encoding="utf-8"),
    }


def read_local(repo: Path, rel: str) -> str | None:
    path = repo / rel
    return path.read_text(encoding="utf-8") if path.is_file() else None


def check_local(repo: Path, sealed: bool) -> list[str]:
    expected = None if sealed else canonical_body()
    files = None if sealed else {rel: read_local(repo, rel) for rel in generated_files()}
    agents_md = read_local(repo, "AGENTS.md")
    found = problems_for(
        agents_md,
        (repo / "CLAUDE.md").exists() or (repo / "CLAUDE.md").is_symlink(),
        expected,
        files,
    )
    if agents_md is not None:
        config = read_config(repo)
        if isinstance(config, str):
            found.append(config)
        else:
            found += doc_problems(agents_md, repo, datetime.date.today(), config)
    return found


def gh_contents(repo: str, rel: str, jq: str) -> str | None:
    """None when the path is absent on the default branch; any other gh failure stops the check."""
    result = subprocess.run(
        ["gh", "api", f"repos/{repo}/contents/{rel}", "--jq", jq],
        capture_output=True,
        text=True,
    )
    if result.returncode != 0:
        if "Not Found" in result.stderr or "404" in result.stderr:
            return None
        raise SystemExit(f"gh api failed for {repo}/{rel}: {result.stderr.strip()}")
    return result.stdout


def gh_file(repo: str, rel: str) -> str | None:
    content = gh_contents(repo, rel, ".content")
    return None if content is None else base64.b64decode(content).decode("utf-8")


def check_remote(repo: str) -> list[str]:
    files = {rel: gh_file(repo, rel) for rel in generated_files()}
    claude_md_exists = gh_contents(repo, "CLAUDE.md", ".path") is not None
    return problems_for(gh_file(repo, "AGENTS.md"), claude_md_exists, canonical_body(), files)


def cmd_render(args) -> int:
    sys.stdout.write(render(canonical_body()))
    return 0


def cmd_sync(args) -> int:
    body = canonical_body()
    for repo in map(Path, args.repos):
        agents = repo / "AGENTS.md"
        current = agents.read_text(encoding="utf-8") if agents.exists() else "# Agent instructions\n"
        agents.write_text(with_block(current, body), encoding="utf-8")
        for rel, content in generated_files().items():
            (repo / rel).parent.mkdir(parents=True, exist_ok=True)
            (repo / rel).write_text(content, encoding="utf-8")
        print(f"synced {repo}")
    return 0


def cmd_check(args) -> int:
    if args.remote:
        targets = args.repos or json.loads(CONSUMERS.read_text(encoding="utf-8"))["repos"]
        results = {repo: check_remote(repo) for repo in targets}
    else:
        if not args.repos:
            raise SystemExit("check needs at least one checkout directory, or --remote")
        results = {repo: check_local(Path(repo), args.sealed) for repo in args.repos}
    failed = 0
    for repo, problems in results.items():
        if not problems:
            print(f"ok {repo}")
        for problem in problems:
            print(f"! {repo}: {problem}", file=sys.stderr)
        failed += bool(problems)
    return 1 if failed else 0


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("render").set_defaults(func=cmd_render)
    p = sub.add_parser("sync")
    p.add_argument("repos", nargs="+")
    p.set_defaults(func=cmd_sync)
    p = sub.add_parser("check")
    p.add_argument("repos", nargs="*")
    mode = p.add_mutually_exclusive_group()
    mode.add_argument("--sealed", action="store_true", help="check only that the block was not hand-edited")
    mode.add_argument("--remote", action="store_true", help="read repositories through gh api")
    p.set_defaults(func=cmd_check)
    args = parser.parse_args()
    return args.func(args)


if __name__ == "__main__":
    sys.exit(main())
